const assert = require('assert');
const { total, describe } = require('./build/cart.js');
const items = [
  { name: 'pen', price: 2.5, quantity: 4 },
  { name: 'pad', price: 5.0, quantity: 1 },
];
assert.strictEqual(total(items, 0.1), 16.5, 'total with 10% tax');
assert.strictEqual(total([], 0.2), 0, 'empty cart');
assert.strictEqual(describe(items[0]), 'pen x4 @ 2.5');
